Rules.InvariantScript:
UpdateContext(
    {
        var_visibleForms: false,
        newMode: false,
        editMode: false,
        isItemSelected: false,
        CurrentItem: Blank()
    } 
);
ResetForm(FormCSO)

UpdateContext(
    {
        isItemSelected: true,
        newMode: false,
        editMode: false,
        CurrentItem: ThisItem
    }
);
Clear(col_partipantes);
ForAll(
    Split(
        ThisItem.Outros_Particpantes,
        "; "
    ),
    Collect(
        col_partipantes,
        {
            nome: First(
                Split(
                    ThisRecord.Value,
                    " - "
                )
            ).Value,
            empresa: Last(
                Split(
                    ThisRecord.Value,
                    " - "
                )
            ).Value
        }
    )
);

RemoveIf(
    tbl_desdobramentos,
    ID_ocorrencia = CurrentItem.ID
);
Remove(
    '1 - CSO',
    CurrentItem
);
If(
    IsEmpty(
        Errors(
            '1 - CSO',
            CurrentItem
        )
    ),
    Navigate(
        ScreenSucesso,
        ScreenTransition.Fade,
        {var_navigateSucess: ScreenCSO}
    );
    UpdateContext(
        {
            isItemSelected: false,
            newMode: false,
            deleteMode: false
        }
    )
);

ControlPropertyState.AutoRuleBindingString:
Remove(
    Table(),
    selectedRecord
);
If(
    IsEmpty(
        Errors(
            Table(),
            selectedRecord
        )
    ),
    UpdateContext(
        {
            CurrentItem: First(Table()),
            isItemSelected: false,
            newMode: false,
            deleteMode: false
        }
    )
);

Rules.InvariantScript:
NewForm(FormCSO);
UpdateContext(
    {
        newMode: true,
        CurrentItem: Blank(),
        var_selectTipoFOD: Blank()
    }
);
Clear(col_partipantes)

Navigate(
    ScreenDesdobramentos,
    ScreenTransition.Fade,
    {
        var_desdobramentosSelect: {
            ID: Value(CurrentItem.ID),
            PROTOCOLO: Text(
                LookUp(
                    colAeros,
                    Aeroporto = CurrentItem.Aeroporto
                ).IATA & "-CSO-" & CurrentItem.ID
            ),
            CRIADOR: Text(CurrentItem.'Criado por'.DisplayName),
            DESCRICAO: Text(CurrentItem.Assuntos_Abordados)
        }
    }
)

ControlPropertyState.AutoRuleBindingString:
Navigate(
    ScreenDesdobramentos,
    ScreenTransition.Fade,
    {
        var_desdobramentosSelect: {
            ID: Value(ThisItem.colVei_id),
            PROTOCOLO: Text(Label_protocolo.Text),
            CRIADOR: Text(ThisItem.'Criado por'.DisplayName),
            DESCRICAO: Text(ThisItem.colVei_descOcorrencia)
        }
    }
)

Rules.InvariantScript:
Set(
    varIDhtmlCriado,
